// src/create-harness.ts
init_patch();
function stableStringify(value) {
  if (value === null) return "null";
  if (typeof value === "number") return Number.isFinite(value) ? JSON.stringify(value) : "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "boolean") return value ? "true" : "false";
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  if (typeof value === "object") {
    const keys = Object.keys(value).sort();
    const parts = keys.map(
      (k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`
    );
    return `{${parts.join(",")}}`;
  }
  return "null";
}
function shortHash(input2) {
  return createHash("sha256").update(input2).digest("hex").slice(0, 12);
}
function hashClassification(c) {
  return shortHash(stableStringify({ vector: c.vector, riskTier: c.riskTier }));
}
function computeHarnessId(input2) {
  return shortHash(stableStringify(input2));
}
function computeHarnessName(input2) {
  const v2 = input2.classification.vector;
  const dominantAxes = [];
  if (v2.state !== "none") dominantAxes.push(`state=${v2.state}`);
  if (v2.writes !== "none") dominantAxes.push(`writes=${v2.writes}`);
  if (v2.realtime !== "none") dominantAxes.push(`realtime=${v2.realtime}`);
  if (v2.tooling !== "none") dominantAxes.push(`tooling=${v2.tooling}`);
  const axesPart = dominantAxes.length > 0 ? dominantAxes.join("+") : "passive";
  return `${input2.version}/${axesPart}/${input2.workflowName}`;
}

