// src/harness/check/runtime-render/index.ts
async function warmupRuntimeRenderProbe() {
  const start = Date.now();
  let loaded = 0;
  let missing = 0;
  const tryLoad = async (specifier) => {
    try {
      await import(specifier);
      loaded += 1;
    } catch {
      missing += 1;
    }
  };
  await Promise.all([
    tryLoad("happy-dom"),
    tryLoad("@testing-library/react"),
    tryLoad("@testing-library/user-event"),
    tryLoad("@ggui-ai/wire")
  ]);
  return { ms: Date.now() - start, loaded, missing };
}

