  const selfCheckPassed = tier0Fails.length === 0;
  const violations = tier0Issues.filter((i) => i.result === "fail").map((i) => contextPolicy?.labeledTier0 ? `[${i.priority ?? "P0"}-${i.category}] ${i.description}
  Fix: ${i.fix}` : `[${i.category}] ${i.description}
  Fix: ${i.fix}`);
